import { describe, expect, test } from "bun:test";
import { validateJson } from "./validate-json";

describe("validateJson", () => {
  test("returns true for valid JSON object", () => {
    expect(validateJson('{"key": "value"}')).toBe(true);
  });

  test("returns true for valid JSON array", () => {
    expect(validateJson('[1, 2, 3]')).toBe(true);
  });

  test("returns false for invalid JSON", () => {
    expect(validateJson('{invalid}')).toBe(false);
  });

  test("returns true for valid JSON primitives", () => {
    expect(validateJson('"string"')).toBe(true);
    expect(validateJson('123')).toBe(true);
    expect(validateJson('true')).toBe(true);
    expect(validateJson('null')).toBe(true);
  });

  test("returns false for empty input", () => {
    expect(validateJson('')).toBe(false);
  });

  test("returns false for malformed JSON", () => {
    expect(validateJson('{"key": }')).toBe(false);
    expect(validateJson('[1, 2, 3')).toBe(false);
    expect(validateJson('{"key": "value",}')).toBe(false);
  });

  test("returns true for nested JSON structures", () => {
    expect(validateJson('{"outer": {"inner": "value"}}')).toBe(true);
    expect(validateJson('[{"a": 1}, {"b": 2}]')).toBe(true);
  });

  test("returns true for JSON with special characters", () => {
    expect(validateJson('{"key": "value\\nwith\\nnewlines"}')).toBe(true);
    expect(validateJson('{"unicode": "\\u0048\\u0065\\u006c\\u006c\\u006f"}')).toBe(true);
  });

  test("returns true for large JSON payloads", () => {
    const largeArray = JSON.stringify(Array(1000).fill({ key: "value" }));
    expect(validateJson(largeArray)).toBe(true);
  });
});

