import { describe, test, expect } from "bun:test";
import {
  isString,
  isNumber,
  isBoolean,
  isArray,
  isObject,
  validateJson,
  type ValidationSchema,
} from "./validator";

describe("Type Checking Functions", () => {
  describe("isString", () => {
    test("returns true for strings", () => {
      expect(isString("hello")).toBe(true);
      expect(isString("")).toBe(true);
    });

    test("returns false for non-strings", () => {
      expect(isString(123)).toBe(false);
      expect(isString(null)).toBe(false);
      expect(isString(undefined)).toBe(false);
      expect(isString([])).toBe(false);
    });
  });

  describe("isNumber", () => {
    test("returns true for numbers", () => {
      expect(isNumber(123)).toBe(true);
      expect(isNumber(0)).toBe(true);
      expect(isNumber(-45.67)).toBe(true);
    });

    test("returns false for non-numbers", () => {
      expect(isNumber("123")).toBe(false);
      expect(isNumber(NaN)).toBe(false);
      expect(isNumber(null)).toBe(false);
    });
  });

  describe("isBoolean", () => {
    test("returns true for booleans", () => {
      expect(isBoolean(true)).toBe(true);
      expect(isBoolean(false)).toBe(true);
    });

    test("returns false for non-booleans", () => {
      expect(isBoolean(1)).toBe(false);
      expect(isBoolean("true")).toBe(false);
      expect(isBoolean(null)).toBe(false);
    });
  });

  describe("isArray", () => {
    test("returns true for arrays", () => {
      expect(isArray([])).toBe(true);
      expect(isArray([1, 2, 3])).toBe(true);
    });

    test("returns false for non-arrays", () => {
      expect(isArray({})).toBe(false);
      expect(isArray("[]")).toBe(false);
      expect(isArray(null)).toBe(false);
    });
  });

  describe("isObject", () => {
    test("returns true for plain objects", () => {
      expect(isObject({})).toBe(true);
      expect(isObject({ a: 1 })).toBe(true);
    });

    test("returns false for non-objects", () => {
      expect(isObject([])).toBe(false);
      expect(isObject(null)).toBe(false);
      expect(isObject("{}")).toBe(false);
      expect(isObject(123)).toBe(false);
    });
  });
});

describe("JSON Validation", () => {
  describe("validateJson - parsing", () => {
    test("parses valid JSON string", () => {
      const result = validateJson('{"name": "test"}');
      expect(result.valid).toBe(true);
      expect(result.data).toEqual({ name: "test" });
      expect(result.errors).toEqual([]);
    });

    test("rejects invalid JSON string", () => {
      const result = validateJson("{invalid}");
      expect(result.valid).toBe(false);
      expect(result.data).toBeNull();
      expect(result.errors.length).toBeGreaterThan(0);
      expect(result.errors[0]).toContain("JSON");
    });

    test("handles empty string", () => {
      const result = validateJson("");
      expect(result.valid).toBe(false);
      expect(result.errors[0]).toContain("JSON");
    });
  });

  describe("validateJson - schema validation", () => {
    test("validates required fields", () => {
      const schema: ValidationSchema = {
        type: "object",
        required: ["name", "age"],
        properties: {
          name: { type: "string" },
          age: { type: "number" },
        },
      };

      const validResult = validateJson('{"name": "John", "age": 30}', schema);
      expect(validResult.valid).toBe(true);
      expect(validResult.errors).toEqual([]);

      const missingField = validateJson('{"name": "John"}', schema);
      expect(missingField.valid).toBe(false);
      expect(missingField.errors[0]).toContain("age");
      expect(missingField.errors[0]).toContain("required");
    });

    test("validates property types", () => {
      const schema: ValidationSchema = {
        type: "object",
        properties: {
          name: { type: "string" },
          age: { type: "number" },
          active: { type: "boolean" },
        },
      };

      const wrongType = validateJson(
        '{"name": 123, "age": "30", "active": "true"}',
        schema
      );
      expect(wrongType.valid).toBe(false);
      expect(wrongType.errors.length).toBe(3);
    });

    test("validates nested properties", () => {
      const schema: ValidationSchema = {
        type: "object",
        required: ["user"],
        properties: {
          user: {
            type: "object",
            required: ["email"],
            properties: {
              email: { type: "string" },
              verified: { type: "boolean" },
            },
          },
        },
      };

      const validNested = validateJson(
        '{"user": {"email": "test@example.com", "verified": true}}',
        schema
      );
      expect(validNested.valid).toBe(true);

      const missingNested = validateJson('{"user": {"verified": true}}', schema);
      expect(missingNested.valid).toBe(false);
      expect(missingNested.errors[0]).toContain("email");

      const wrongNestedType = validateJson(
        '{"user": {"email": 123, "verified": true}}',
        schema
      );
      expect(wrongNestedType.valid).toBe(false);
      expect(wrongNestedType.errors[0]).toContain("email");
    });

    test("validates array types", () => {
      const schema: ValidationSchema = {
        type: "object",
        properties: {
          tags: { type: "array" },
        },
      };

      const validArray = validateJson('{"tags": ["a", "b"]}', schema);
      expect(validArray.valid).toBe(true);

      const wrongArrayType = validateJson('{"tags": "not-array"}', schema);
      expect(wrongArrayType.valid).toBe(false);
    });

    test("validates without schema", () => {
      const result = validateJson('{"any": "value"}');
      expect(result.valid).toBe(true);
      expect(result.data).toEqual({ any: "value" });
    });
  });

  describe("validateJson - error messages", () => {
    test("provides clear error messages for missing required fields", () => {
      const schema: ValidationSchema = {
        type: "object",
        required: ["email", "password"],
        properties: {},
      };

      const result = validateJson('{"email": "test@test.com"}', schema);
      expect(result.valid).toBe(false);
      expect(result.errors[0]).toContain("password");
      expect(result.errors[0]).toContain("required");
    });

    test("provides clear error messages for type mismatches", () => {
      const schema: ValidationSchema = {
        type: "object",
        properties: {
          count: { type: "number" },
        },
      };

      const result = validateJson('{"count": "not-a-number"}', schema);
      expect(result.valid).toBe(false);
      expect(result.errors[0]).toContain("count");
      expect(result.errors[0]).toContain("number");
    });

    test("accumulates multiple errors", () => {
      const schema: ValidationSchema = {
        type: "object",
        required: ["a", "b"],
        properties: {
          a: { type: "string" },
          b: { type: "number" },
        },
      };

      const result = validateJson('{"a": 123}', schema);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBe(2);
    });
  });
});

export interface ValidationSchema {
  type: "object" | "array" | "string" | "number" | "boolean";
  required?: string[];
  properties?: Record<string, PropertySchema>;
}

export interface PropertySchema {
  type: "object" | "array" | "string" | "number" | "boolean";
  required?: string[];
  properties?: Record<string, PropertySchema>;
}

export interface ValidationResult {
  valid: boolean;
  data: unknown | null;
  errors: string[];
}

export function isString(value: unknown): value is string {
  return typeof value === "string";
}

export function isNumber(value: unknown): value is number {
  return typeof value === "number" && !Number.isNaN(value);
}

export function isBoolean(value: unknown): value is boolean {
  return typeof value === "boolean";
}

export function isArray(value: unknown): value is unknown[] {
  return Array.isArray(value);
}

export function isObject(value: unknown): value is Record<string, unknown> {
  return (
    typeof value === "object" && value !== null && !Array.isArray(value)
  );
}

function validateType(
  value: unknown,
  expectedType: string,
  path: string
): string | null {
  switch (expectedType) {
    case "string":
      if (!isString(value)) {
        return `Property '${path}' must be of type string`;
      }
      break;
    case "number":
      if (!isNumber(value)) {
        return `Property '${path}' must be of type number`;
      }
      break;
    case "boolean":
      if (!isBoolean(value)) {
        return `Property '${path}' must be of type boolean`;
      }
      break;
    case "array":
      if (!isArray(value)) {
        return `Property '${path}' must be of type array`;
      }
      break;
    case "object":
      if (!isObject(value)) {
        return `Property '${path}' must be of type object`;
      }
      break;
  }
  return null;
}

function validateSchema(
  data: unknown,
  schema: ValidationSchema | PropertySchema,
  path = ""
): string[] {
  const errors: string[] = [];

  if (!isObject(data)) {
    errors.push(`Expected object at '${path || "root"}'`);
    return errors;
  }

  if (schema.required) {
    for (const field of schema.required) {
      if (!(field in data)) {
        const fieldPath = path ? `${path}.${field}` : field;
        errors.push(`Property '${fieldPath}' is required`);
      }
    }
  }

  if (schema.properties) {
    for (const [key, propSchema] of Object.entries(schema.properties)) {
      if (key in data) {
        const value = data[key];
        const fieldPath = path ? `${path}.${key}` : key;

        const typeError = validateType(value, propSchema.type, fieldPath);
        if (typeError) {
          errors.push(typeError);
        } else if (propSchema.type === "object" && isObject(value)) {
          const nestedErrors = validateSchema(value, propSchema, fieldPath);
          errors.push(...nestedErrors);
        }
      }
    }
  }

  return errors;
}

export function validateJson(
  jsonString: string,
  schema?: ValidationSchema
): ValidationResult {
  let data: unknown;

  try {
    data = JSON.parse(jsonString);
  } catch (error) {
    return {
      valid: false,
      data: null,
      errors: [`Invalid JSON: ${error instanceof Error ? error.message : "Parse error"}`],
    };
  }

  if (!schema) {
    return {
      valid: true,
      data,
      errors: [],
    };
  }

  const errors = validateSchema(data, schema);

  return {
    valid: errors.length === 0,
    data: errors.length === 0 ? data : null,
    errors,
  };
}

