    11→}
    12→
    13→export interface ValidationResult {
    14→  valid: boolean;
    15→  data: unknown | null;
    16→  errors: string[];
    17→}
    18→
    19→export function isString(value: unknown): value is string {
    20→  return typeof value === "string";
    21→}
    22→
    23→export function isNumber(value: unknown): value is number {
    24→  return typeof value === "number" && !Number.isNaN(value);
    25→}
    26→
    27→export function isBoolean(value: unknown): value is boolean {
    28→  return typeof value === "boolean";
    29→}
    30→
    31→export function isArray(value: unknown): value is unknown[] {
    32→  return Array.isArray(value);
    33→}
    34→
    35→export function isObject(value: unknown): value is Record<string, unknown> {
    36→  return (
    37→    typeof value === "object" && value !== null && !Array.isArray(value)
    38→  );
    39→}
    40→
    41→function validateType(
    42→  value: unknown,
    43→  expectedType: string,
    44→  path: string
    45→): string | null {
    46→  switch (expectedType) {
    47→    case "string":
    48→      if (!isString(value)) {
    49→        return `Property '${path}' must be of type string`;
    50→      }
    51→      break;
    52→    case "number":
    53→      if (!isNumber(value)) {
    54→        return `Property '${path}' must be of type number`;
    55→      }
    56→      break;
    57→    case "boolean":
    58→      if (!isBoolean(value)) {
    59→        return `Property '${path}' must be of type boolean`;
    60→      }
    61→      break;
    62→    case "array":
    63→      if (!isArray(value)) {
    64→        return `Property '${path}' must be of type array`;
    65→      }
    66→      break;
    67→    case "object":
    68→      if (!isObject(value)) {
    69→        return `Property '${path}' must be of type object`;
    70→      }
    71→      break;
    72→  }
    73→  return null;
    74→}
    75→
    76→function validateSchema(
    77→  data: unknown,
    78→  schema: ValidationSchema | PropertySchema,
    79→  path = ""
    80→): string[] {
    81→  const errors: string[] = [];
    82→
    83→  if (!isObject(data)) {
    84→    errors.push(`Expected object at '${path || "root"}'`);
    85→    return errors;
    86→  }
    87→
    88→  if (schema.required) {
    89→    for (const field of schema.required) {
    90→      if (!(field in data)) {
    91→        const fieldPath = path ? `${path}.${field}` : field;
    92→        errors.push(`Property '${fieldPath}' is required`);
    93→      }
    94→    }
    95→  }
    96→
    97→  if (schema.properties) {
    98→    for (const [key, propSchema] of Object.entries(schema.properties)) {
    99→      if (key in data) {
   100→        const value = data[key];
   101→        const fieldPath = path ? `${path}.${key}` : key;
   102→
   103→        const typeError = validateType(value, propSchema.type, fieldPath);
   104→        if (typeError) {
   105→          errors.push(typeError);
   106→        } else if (propSchema.type === "object" && isObject(value)) {
   107→          const nestedErrors = validateSchema(value, propSchema, fieldPath);
   108→          errors.push(...nestedErrors);
   109→        }
   110→      }
   111→    }
   112→  }
   113→
   114→  return errors;
   115→}
   116→
   117→export function validateJson(
   118→  jsonString: string,
   119→  schema?: ValidationSchema
   120→): ValidationResult {
   121→  let data: unknown;
   122→
   123→  try {
   124→    data = JSON.parse(jsonString);
   125→  } catch (error) {
   126→    return {
   127→      valid: false,
   128→      data: null,
   129→      errors: [`Invalid JSON: ${error instanceof Error ? error.message : "Parse error"}`],
   130→    };
   131→  }
   132→
   133→  if (!schema) {
   134→    return {
   135→      valid: true,
   136→      data,
   137→      errors: [],
   138→    };
   139→  }
   140→
   141→  const errors = validateSchema(data, schema);
   142→
   143→  return {
   144→    valid: errors.length === 0,
   145→    data: errors.length === 0 ? data : null,
   146→    errors,
   147→  };
   148→}
