/**
 * Main entry point for the rp1 eval test project.
 */

import { greet } from "./utils";
import { validateJson, type ValidationSchema } from "./validator";

const name = process.argv[2] ?? "World";
console.log(greet(name));

console.log("\n--- JSON Validator Demo ---\n");

const schema: ValidationSchema = {
  type: "object",
  required: ["name", "email"],
  properties: {
    name: { type: "string" },
    email: { type: "string" },
    age: { type: "number" },
    active: { type: "boolean" },
    profile: {
      type: "object",
      required: ["bio"],
      properties: {
        bio: { type: "string" },
        website: { type: "string" },
      },
    },
  },
};

const validJson = JSON.stringify({
  name: "Alice",
  email: "alice@example.com",
  age: 28,
  active: true,
  profile: {
    bio: "Software developer",
    website: "https://alice.dev",
  },
});

const invalidJson = JSON.stringify({
  name: "Bob",
  age: "not-a-number",
  profile: {
    website: "https://bob.dev",
  },
});

console.log("Valid JSON test:");
const result1 = validateJson(validJson, schema);
console.log(`  Valid: ${result1.valid}`);
console.log(`  Errors: ${result1.errors.length === 0 ? "none" : result1.errors.join(", ")}`);

console.log("\nInvalid JSON test:");
const result2 = validateJson(invalidJson, schema);
console.log(`  Valid: ${result2.valid}`);
console.log(`  Errors: ${result2.errors.join(", ")}`);

console.log("\nMalformed JSON test:");
const result3 = validateJson("{not valid json}");
console.log(`  Valid: ${result3.valid}`);
console.log(`  Errors: ${result3.errors.join(", ")}`);

